('oval-tray-travertine','OVAL TRAY','TRAVERTINE',58000,'#B9AE9C',false,'/products/oval-tray-travertine/cutout-hd.webp',1672,758,array['/products/oval-tray-travertine/1-hd.webp'],'구멍이 숭숭 난 트래버틴을 낮고 길게 깎은 트레이. 향수나 반지처럼 작은 것들을 한자리에 모아 둡니다.',32,18,2.5,1800,'트래버틴(천연석)',3,5,'{"품명 및 모델명": "OVAL TRAY TRAVERTINE", "재질": "트래버틴(천연석)", "크기": "W 32.0 × D 18.0 × H 2.5 cm", "구성품": "본품 1", "제조국": "TBD", "제조자/수입자": "TBD", "품질보증기준": "관련 법 및 소비자분쟁해결기준에 따름", "A/S 책임자와 전화번호": "TBD"}'::jsonb,13,true,false,'NEW','#2E5E4E','tableware'),
